<?php
/**
 * Web Push with no library: VAPID signing (RFC 8292) and aes128gcm payload encryption
 * (RFC 8291), done with PHP's own OpenSSL. Replaces the Composer package
 * minishlink/web-push, which was never installed on the server, so every push was
 * silently skipped.
 *
 * VAPID keys: VAPID_PUBLIC_KEY / VAPID_PRIVATE_KEY (base64url, as generated by any
 * web-push tool) in .env if set; otherwise generated once and kept in the push_vapid
 * table, so push works without editing .env. VAPID_SUBJECT optional.
 *
 *   wpVapidKeys($conn)                         ['public' => b64u, 'private' => b64u, 'subject' => ...]
 *   wpSend($vapid, $endpoint, $p256dh, $auth, $payload)   ['ok' => bool, 'status' => int, 'expired' => bool, 'error' => ?string]
 */
require_once __DIR__ . '/env_loader.php';

if (!function_exists('wpSend')) {

    function wpB64u(string $bin): string { return rtrim(strtr(base64_encode($bin), '+/', '-_'), '='); }
    function wpB64uDecode(string $s): string { $s = strtr($s, '-_', '+/'); return (string)base64_decode($s . str_repeat('=', (4 - strlen($s) % 4) % 4)); }

    /** OpenSSL key options; Windows PHP often can't find openssl.cnf on its own. */
    function wpKeyArgs(): array {
        $args = ['curve_name' => 'prime256v1', 'private_key_type' => OPENSSL_KEYTYPE_EC];
        static $cfg = null;
        if ($cfg === null) {
            $cfg = '';
            if (!@openssl_pkey_new($args)) {
                while (openssl_error_string()) {}
                $dir = dirname(PHP_BINARY);
                foreach ([getenv('OPENSSL_CONF') ?: '', $dir . '/extras/ssl/openssl.cnf', $dir . '/extras/openssl/openssl.cnf', dirname($dir) . '/apache/conf/openssl.cnf', 'C:/xampp/apache/conf/openssl.cnf'] as $c) {
                    if ($c && is_file($c) && @openssl_pkey_new($args + ['config' => $c])) { $cfg = $c; break; }
                }
            }
        }
        return $cfg ? $args + ['config' => $cfg] : $args;
    }

    /** New P-256 key: [OpenSSL key, uncompressed public point (65 bytes), private scalar (32 bytes)]. */
    function wpNewKey(): array {
        $k = openssl_pkey_new(wpKeyArgs());
        if (!$k) throw new RuntimeException('Could not create an EC key: ' . openssl_error_string());
        $d = openssl_pkey_get_details($k)['ec'];
        $pad = function ($v) { return str_pad($v, 32, "\0", STR_PAD_LEFT); };
        return [$k, "\x04" . $pad($d['x']) . $pad($d['y']), $pad($d['d'])];
    }

    /** PEM for a P-256 private key from its raw parts (SEC1 ECPrivateKey). */
    function wpPrivatePem(string $d, string $pub): string {
        $der = hex2bin('30770201010420') . $d . hex2bin('a00a06082a8648ce3d030107a144034200') . $pub;
        return "-----BEGIN EC PRIVATE KEY-----\n" . chunk_split(base64_encode($der), 64, "\n") . "-----END EC PRIVATE KEY-----\n";
    }
    /** PEM for a P-256 public key from its uncompressed point (SubjectPublicKeyInfo). */
    function wpPublicPem(string $pub): string {
        $der = hex2bin('3059301306072a8648ce3d020106082a8648ce3d030107034200') . $pub;
        return "-----BEGIN PUBLIC KEY-----\n" . chunk_split(base64_encode($der), 64, "\n") . "-----END PUBLIC KEY-----\n";
    }

    function wpVapidKeys(PDO $conn): array {
        $subject = (string)env('VAPID_SUBJECT', 'mailto:admin@restrogrow.com');
        $pub = trim((string)env('VAPID_PUBLIC_KEY', '')); $priv = trim((string)env('VAPID_PRIVATE_KEY', ''));
        if ($pub !== '' && $priv !== '') return ['public' => $pub, 'private' => $priv, 'subject' => $subject];
        static $cache = null;
        if ($cache) return $cache;
        $conn->exec('CREATE TABLE IF NOT EXISTS push_vapid (id TINYINT PRIMARY KEY, public_key VARCHAR(120) NOT NULL, private_key VARCHAR(80) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)');
        $row = $conn->query('SELECT public_key, private_key FROM push_vapid WHERE id = 1')->fetch(PDO::FETCH_ASSOC);
        if (!$row) {
            [, $p, $d] = wpNewKey();
            $conn->prepare('INSERT IGNORE INTO push_vapid (id, public_key, private_key) VALUES (1, ?, ?)')->execute([wpB64u($p), wpB64u($d)]);
            $row = $conn->query('SELECT public_key, private_key FROM push_vapid WHERE id = 1')->fetch(PDO::FETCH_ASSOC);
        }
        return $cache = ['public' => $row['public_key'], 'private' => $row['private_key'], 'subject' => $subject];
    }

    /** ECDSA signature: DER from OpenSSL → raw r||s (64 bytes) for a JWT. */
    function wpDerToRaw(string $der): string {
        $o = 2;                                   // SEQUENCE tag + length (P-256 signatures are < 128 bytes)
        $out = '';
        for ($i = 0; $i < 2; $i++) {
            $len = ord($der[$o + 1]);
            $int = substr($der, $o + 2, $len);
            $out .= str_pad(ltrim($int, "\0"), 32, "\0", STR_PAD_LEFT);
            $o += 2 + $len;
        }
        return $out;
    }

    function wpVapidHeader(array $vapid, string $endpoint): string {
        $u = parse_url($endpoint);
        $aud = $u['scheme'] . '://' . $u['host'] . (isset($u['port']) ? ':' . $u['port'] : '');
        $data = wpB64u(json_encode(['typ' => 'JWT', 'alg' => 'ES256'])) . '.' . wpB64u(json_encode(['aud' => $aud, 'exp' => time() + 12 * 3600, 'sub' => $vapid['subject']]));
        $pem = wpPrivatePem(wpB64uDecode($vapid['private']), wpB64uDecode($vapid['public']));
        if (!openssl_sign($data, $sig, $pem, OPENSSL_ALGO_SHA256)) throw new RuntimeException('VAPID signing failed: ' . openssl_error_string());
        return 'vapid t=' . $data . '.' . wpB64u(wpDerToRaw($sig)) . ', k=' . $vapid['public'];
    }

    /** RFC 8291 aes128gcm body for one subscription. */
    function wpEncrypt(string $payload, string $uaPublicB64u, string $authB64u): string {
        $uaPublic = wpB64uDecode($uaPublicB64u);
        $auth = wpB64uDecode($authB64u);
        if (strlen($uaPublic) !== 65 || strlen($auth) < 16) throw new RuntimeException('Bad subscription keys');
        [$asKey, $asPublic] = wpNewKey();
        $ecdh = openssl_pkey_derive(openssl_pkey_get_public(wpPublicPem($uaPublic)), $asKey, 32);
        if ($ecdh === false) throw new RuntimeException('ECDH failed: ' . openssl_error_string());
        $ikm = hash_hkdf('sha256', $ecdh, 32, "WebPush: info\0" . $uaPublic . $asPublic, $auth);
        $salt = random_bytes(16);
        $cek = hash_hkdf('sha256', $ikm, 16, "Content-Encoding: aes128gcm\0", $salt);
        $nonce = hash_hkdf('sha256', $ikm, 12, "Content-Encoding: nonce\0", $salt);
        $tag = '';
        $ct = openssl_encrypt($payload . "\x02", 'aes-128-gcm', $cek, OPENSSL_RAW_DATA, $nonce, $tag, '', 16);
        if ($ct === false) throw new RuntimeException('Encryption failed');
        return $salt . pack('N', 4096) . chr(65) . $asPublic . $ct . $tag;
    }

    function wpSend(array $vapid, string $endpoint, string $p256dh, string $auth, string $payload, int $ttl = 86400, string $urgency = 'high'): array {
        try {
            $body = wpEncrypt($payload, $p256dh, $auth);
            $ch = curl_init($endpoint);
            curl_setopt_array($ch, [CURLOPT_POST => true, CURLOPT_POSTFIELDS => $body, CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 10, CURLOPT_CONNECTTIMEOUT => 5,
                CURLOPT_HTTPHEADER => ['Content-Type: application/octet-stream', 'Content-Encoding: aes128gcm', 'TTL: ' . $ttl, 'Urgency: ' . $urgency,
                                       'Authorization: ' . wpVapidHeader($vapid, $endpoint)]]);
            // also trust the system's certificate store (Windows PHP often has no CA bundle configured)
            if (defined('CURLSSLOPT_NATIVE_CA')) curl_setopt($ch, CURLOPT_SSL_OPTIONS, CURLSSLOPT_NATIVE_CA);
            $res = curl_exec($ch);
            $status = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
            $err = curl_error($ch);
            curl_close($ch);
            if ($res === false) return ['ok' => false, 'status' => 0, 'expired' => false, 'error' => 'Could not reach the push service: ' . $err];
            return ['ok' => $status >= 200 && $status < 300, 'status' => $status, 'expired' => in_array($status, [404, 410], true),
                    'error' => $status >= 300 ? 'Push service answered ' . $status . ': ' . mb_substr(trim((string)$res), 0, 160) : null];
        } catch (Throwable $e) {
            return ['ok' => false, 'status' => 0, 'expired' => false, 'error' => $e->getMessage()];
        }
    }
}
